import{_ as a,o as d,c as e,a6 as r}from"./chunks/framework.D9iQZIpB.js";const c=JSON.parse('{"title":"功法总览","description":"十个已完整公开的秘传养生术流派总览，含传承归属、公开时间与非遗状况","frontmatter":{"title":"功法总览","description":"十个已完整公开的秘传养生术流派总览，含传承归属、公开时间与非遗状况"},"headers":[],"relativePath":"methods/index.md","filePath":"methods/index.md","lastUpdated":null}'),h={name:"methods/index.md"};function o(n,t,i,l,s,m){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="功法总览" tabindex="-1">功法总览 <a class="header-anchor" href="#功法总览" aria-label="Permalink to &quot;功法总览&quot;">​</a></h1><p>本页所列十个流派，均按输入报告的「有明确公开节点、有系统公开载体、有可追溯传承谱系」三项标准纳入。所有字段照录报告，本站不补充报告之外的史实。</p><div class="warning custom-block"><p class="custom-block-title">阅读前须知</p><p>本站是<strong>文献线索索引</strong>，不是功法教程，也不提供任何医疗、保健或疗效建议。部分历史出版物题名含「防治癌症」「抗衰老」「养生长寿」等字样，属书目编目原题，不代表本站立场，更不构成疗效认定。患病请遵医嘱。</p></div><h2 id="十个流派一览" tabindex="-1">十个流派一览 <a class="header-anchor" href="#十个流派一览" aria-label="Permalink to &quot;十个流派一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>流派</th><th>别名</th><th>公开时间</th><th>传承归属</th><th>非遗状况</th></tr></thead><tbody><tr><td><a href="./m01">千峰先天派性命双修功法</a></td><td>性命双修功法、千峰派内丹养生术</td><td>1933年</td><td>道教龙门派第十一代赵避尘（1860—1942，号千峰老人），全真千峰先天派创始人</td><td>未单独列入非遗名录；席春生为北京市海淀区『千峰派内丹养生术』『道医正骨按摩』两项非物质文化遗产代表性传承人</td></tr><tr><td><a href="./m02">峨眉十二庄</a></td><td>峨眉临济宗气功、峨眉丹道医药养生学派</td><td>1959—1960年</td><td>源于南宋白云禅师，佛门密传近800年，『传僧不传俗』</td><td>乐山市第六批市级非遗（传统体育类）；以『峨眉龙头拐杖制作工艺·峨眉十二庄』名称列入峨眉山市级非遗；作为核心组成部分归属…</td></tr><tr><td><a href="./m03">郭林新气功</a></td><td>新气功疗法</td><td>1971年</td><td>郭林（1909—1984，原名林冠明，岭南派女画家）自幼习练祖父所传道家功法及五禽戏，1959—1970年间改革古气功创编</td><td>未列入非遗名录</td></tr><tr><td><a href="./m04">大雁气功</a></td><td>大雁功、道家昆仑派大雁功</td><td>1978—1980年</td><td>道家昆仑派长期秘传，传自晋代高僧道安；现代传人杨梅君（1903—2002）13岁受祖父杨德山宗传</td><td>2025年3月列入浙江温州龙港市第三批市级非遗名录，保护单位为龙港市陈家处文化传媒服务部</td></tr><tr><td><a href="./m05">武当太乙五行拳</a></td><td>武当太乙五行擒扑二十三式</td><td>1980—1982年</td><td>明弘治年间由武当山道教龙门派第八代宗师张守性创编</td><td>2006年武当武术列入首批国家级非物质文化遗产名录，太乙五行拳作为其组成部分获得制度性保护</td></tr><tr><td><a href="./m06">全真华山派回春功</a></td><td>中国古代养生长寿术秘传回春功</td><td>1980年代初（1984年首次对外公布）</td><td>源于金元时期全真道华山派，传为全真七子之一郝大通创编，历八百余年教内单传，道规『上不传父母，下不传子女，严禁抄录』</td><td>未单独列入国家级或省级名录</td></tr><tr><td><a href="./m07">青城派筋经内丹功</a></td><td>筋经内丹功、筋经导引</td><td>1990年（2018年增补）</td><td>相传为清末民初青城山高道欢喜道人李杰（一说李永宏）所传，历来『只可单传，不可外泄』</td><td>2024年『筋经导引术』列入四川省级非遗，王庆余获批第二代传承人</td></tr><tr><td><a href="./m08">八仙养生手</a></td><td>八仙手</td><td>2008年3月</td><td>传为八仙宫祖师韩湘子所传，为道教内丹筑基功的辅助功法</td><td>未列入非遗名录</td></tr><tr><td><a href="./m09">金刚长寿功</a></td><td>八部金刚功、八部长寿功</td><td>2009年公开传授，2013年出版</td><td>全真龙门派第二十一代张至顺（道号米晶子，1912—2015）17岁于华山遇师刘明苍道长承传；传自玉蟾宫白玉蟾祖师一脉，历代单传口授、无文字留下</td><td>2023年列入湖南省第六批省级非物质文化遗产代表性项目</td></tr><tr><td><a href="./m10">陈撄宁—胡海牙仙学养生术</a></td><td>仙学养生术、胡海牙仙学养生术</td><td>2006年</td><td>近代道学大师陈撄宁首倡并创立仙学体系，原为少数人秘传的内丹修炼之学</td><td>未见名录收录记载</td></tr></tbody></table><blockquote><p>报告原表另列「核心公开载体」与「公开标志」两列，此处为移动端可读性略去，完整信息见各流派详情页。</p></blockquote><h2 id="三次公开浪潮" tabindex="-1">三次公开浪潮 <a class="header-anchor" href="#三次公开浪潮" aria-label="Permalink to &quot;三次公开浪潮&quot;">​</a></h2><h3 id="第一次浪潮-1930年代著书公开-1933年" tabindex="-1">第一次浪潮：1930年代著书公开（1933年） <a class="header-anchor" href="#第一次浪潮-1930年代著书公开-1933年" aria-label="Permalink to &quot;第一次浪潮：1930年代著书公开（1933年）&quot;">​</a></h3><p>赵避尘1933年刊行《性命法诀明指》，将龙门派『外秘』的性命双修十六步功法完整写成文字，打破『三口不说、六耳不传』惯例。</p><p>涉及流派：<a href="./m01">千峰先天派性命双修功法</a></p><h3 id="第二次浪潮-1959—1990年大众化公开高潮-1959—1990年" tabindex="-1">第二次浪潮：1959—1990年大众化公开高潮（1959—1990年） <a class="header-anchor" href="#第二次浪潮-1959—1990年大众化公开高潮-1959—1990年" aria-label="Permalink to &quot;第二次浪潮：1959—1990年大众化公开高潮（1959—1990年）&quot;">​</a></h3><p>周潜川、郭林、杨梅君、金子弢、边治中、王庆余相继以著书出版与公开授功方式公布核心功法。</p><p>涉及流派：<a href="./m02">峨眉十二庄</a>、<a href="./m03">郭林新气功</a>、<a href="./m04">大雁气功</a>、<a href="./m05">武当太乙五行拳</a>、<a href="./m06">全真华山派回春功</a>、<a href="./m07">青城派筋经内丹功</a></p><h3 id="第三次浪潮-2006—2018年新一波公开-2006—2018年" tabindex="-1">第三次浪潮：2006—2018年新一波公开（2006—2018年） <a class="header-anchor" href="#第三次浪潮-2006—2018年新一波公开-2006—2018年" aria-label="Permalink to &quot;第三次浪潮：2006—2018年新一波公开（2006—2018年）&quot;">​</a></h3><p>胡海牙出版《中华仙学养生全书》，八仙宫公开八仙养生手，张至顺公开传授并出版八部金刚功，王庆余2018年再出增补专著。</p><p>涉及流派：<a href="./m08">八仙养生手</a>、<a href="./m09">金刚长寿功</a>、<a href="./m10">陈撄宁—胡海牙仙学养生术</a>、<a href="./m07">青城派筋经内丹功</a></p><h2 id="两条独立线索" tabindex="-1">两条独立线索 <a class="header-anchor" href="#两条独立线索" aria-label="Permalink to &quot;两条独立线索&quot;">​</a></h2><p>报告特别指出：<strong>功法内容的完整公开</strong>与<strong>非遗制度认定</strong>是两条独立线索，前者是传承人的公开行为，后者是文化保护制度，二者并不互为前提。十个流派中仅五个获得各级非遗归属；未获非遗认定不等于未公开，获得认定也不等于核心口诀已全部面世。</p><p>详见 <a href="./../lineage">传承脉络</a> 与 <a href="./../sources">来源说明</a>。</p>',19)])])}const p=a(h,[["render",o]]);export{c as __pageData,p as default};
